import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import type { FilterDataStructure, FilterForm, Option } from 'models/Filters';

function safeStringLabel(label: unknown): string {
  return typeof label === 'string' ? label : '';
}

export function getPerformanceAndBreakdownBrandLabel(
  dataFilters: FilterDataStructure,
  applied: FilterForm,
): string {
  const brandValue = applied.brands;
  if (!brandValue || brandValue === 'All') {
    return '';
  }

  const options = FilterDataAccessor.getInstance().getOptions(
    'brands',
    dataFilters,
    applied,
  ) as Option[];

  for (const option of options) {
    if (String(option.value) === String(brandValue)) {
      return safeStringLabel(option.label) || safeStringLabel(brandValue);
    }
  }

  return safeStringLabel(brandValue);
}
